export interface EventReview {
  id: string;
  userName: string;
  userAvatar: string;
  rating: number;
  date: string;
  comment: string;
  tags?: string[];
}

export type DayOfWeek = 'MO' | 'TU' | 'WE' | 'TH' | 'FR' | 'SA' | 'SU';

export interface EventRecurrence {
  frequency: 'weekly' | 'biweekly' | 'monthly';
  daysOfWeek: DayOfWeek[];
  endType: 'never' | 'on_date';
  endDate?: string;
  customSummary?: string;
}

export interface EventItem {
  id: string;
  title: string;
  date: string;
  endDate?: string;
  time: string;
  location: string;
  tag: string;
  category: 'heal' | 'move' | 'chill' | 'learn';
  /** Meetup group on the ค้นพบ tabs (a communityCategories id), picked by the host; checked by the server */
  lifestyleCategory?: string;
  /** Fair group on the ค้นพบ tabs (a fairCategories id), picked by the organizer; checked by the server */
  fairCategory?: string;
  image: string;
  participantsCount: number;
  maxParticipants: number;
  hostName: string;
  hostAvatar?: string;
  hostId?: string;
  source?: string;
  sourceUrl?: string;
  price?: string;
  description: string;
  isTrending?: boolean;
  isNew?: boolean;
  isHost?: boolean;
  rating?: number;
  reviewsCount?: number;
  hostHostedCount?: number;
  hostRating?: number;
  hostReviewsCount?: number;
  hostBadgeTier?: 'new' | 'verified' | 'superhost';
  reviews?: EventReview[];
  badgeText?: string;
  createdAtTimestamp: number;
  eventType?: 'community' | 'public_venue';
  venueTag?: 'qsncc' | 'bitec' | 'impact' | 'marathon' | 'park';
  externalUrl?: string;
  targetGender?: 'all' | 'female_only' | 'male_only' | string;
  targetAge?: string;
  energyLevel?: 'chill' | 'active' | string;
  latitude?: number;
  longitude?: number;
  zone?: string;
  province?: string;
  scheduleType?: 'single' | 'recurring';
  recurrence?: EventRecurrence;
  /** One date of a recurring ตี้: the series it belongs to (lib/social/recurring.ts). Not listed on its own. */
  seriesId?: string;
  locationType?: 'physical' | 'online';
  onlinePlatform?: 'zoom' | 'google_meet' | 'discord' | 'teams' | 'other' | string;
  onlineJoinUrl?: string;
  meetingPoint?: string;
  /** Spot Buddy trip: the place it is tied to, set by the server from the spot record */
  spotId?: string;
  spotTitle?: string;
  /** A ตี้'s place picked from our catalog (not a Spot Buddy trip, so no trip rules); placeTitle is set by the server */
  placeId?: string;
  placeTitle?: string;
  /** Runs (ThaiRun): the distances in km and whether sign-up is open, shown as rows on the อีเวนต์ page */
  raceDistances?: number[];
  registrationOpen?: boolean;
  /** Spot Buddy trip: people needed (host included) before the trip counts as confirmed */
  minParticipants?: number;
  distanceKm?: number;
  status?: 'upcoming' | 'ongoing' | 'ended' | string;
  buddyCount?: number;
  link?: string;
  galleryImages?: string[];
  rules?: string[];
  whatToBring?: string[];
  contactChannel?: string;
  transportation?: string;
  isSoloFriendly?: boolean;
  isPetFriendly?: boolean;
  isBeginnerFriendly?: boolean;
  isIntrovertFriendly?: boolean;
  canBringFriend?: boolean;
  isEnglishFriendly?: boolean;
  isKidFriendly?: boolean;
  cancellationPolicy?: 'free_anytime' | 'free_24h' | 'free_48h' | 'chat_notice' | string;
  instructions?: string[];
  subActivities?: Array<{ title: string; time?: string; description?: string; location?: string }>;
  itinerary?: Array<{ time: string; title: string }>;
  approvalStatus?: 'approved' | 'pending' | 'rejected' | string;
  rejectionReason?: string;
  moderatedAt?: number;
}

import { BANGKOK_ZONES, calculateDistanceKm } from './zones';

export { BANGKOK_ZONES, calculateDistanceKm };

export interface MoodCategory {
  id: 'heal' | 'move' | 'chill' | 'learn';
  label: string;
  icon: string;
}

/**
 * Who stands behind a quest and what finishing it unlocks.
 * - brand_partner: a partner brand's exclusive voucher (partnerName + title required)
 * - hub_central:   a platform-wide challenge rewarded with Hub points (partnerName = platform)
 */
export interface QuestReward {
  type: 'brand_partner' | 'hub_central';
  title: string;
  /** Short prize label for the challenge card (at most PRIZE_LABEL_MAX characters); the card falls back to a trimmed title */
  shortTitle?: string;
  partnerName: string;
  voucherCodePrefix?: string;
  exclusiveNotice?: string;
  terms?: string;
  hubRewardNote?: string;
}

/**
 * What counts toward a challenge: visits (lib/social/visits.ts) to places, community events or fairs.
 * Every filter given must match. Progress is the number of different targets visited, worked out by the server.
 */
export interface QuestRule {
  targetTypes: ('spot' | 'community' | 'fair')[];
  /** How many different places or events must be visited */
  count: number;
  /** A place's category ('cafe', 'park', ...) or an event's category ('heal', 'move', 'chill', 'learn') */
  categories?: string[];
  provinces?: string[];
  /** Any of these words in the title */
  keywords?: string[];
  /** Only places of these vibes (spotVibes ids such as 'mountain_mist', as grouped on /spots) */
  vibes?: string[];
  /** Only these places or events */
  targetIds?: string[];
  /** Weakest evidence that counts: 'marked' (default), 'moment' (a photo) or 'checkin' (the host's check-in) */
  minEvidence?: 'marked' | 'moment' | 'checkin';
  /** Only visits within this many days of the member's sign-up count (a welcome challenge for new members) */
  newMemberDays?: number;
  /**
   * Counts ตี้ the member hosted instead of ones they went to: a hosted ตี้ counts once at least this many guests
   * were checked in. Use with targetTypes ['community'].
   */
  asHost?: number;
  /** Counts a ตี้ only when at least this many of the member's friends were checked in there too (lib/social/friends.ts) */
  withFriends?: number;
  /** Who is a friend for withFriends: 'invite' (an invite link, either way) or 'any' (also members who follow each other) */
  friendsVia?: 'invite' | 'any';
  /** Counts weekends instead of places: every Saturday–Sunday (Bangkok) with a counted visit is one */
  perWeekend?: boolean;
}

export interface ChallengeQuest {
  id: string;
  title: string;
  iconName: string;
  progressPercent: number;
  current: string;
  total: string;
  badgeLabel: string;
  completedCountInfo: string;
  /** An id of the community categories (master data `communityCategories`), which challenges share since 2026-10-16 */
  category?: string;
  visibility?: 'public' | 'private';
  creatorName?: string;
  creatorAvatar?: string;
  participantsCount?: number;
  rewardPoints?: number;
  targetGoal?: string;
  isOfficial?: boolean;
  objective?: string;
  steps?: string[];
  verificationMethod?: string;
  rewardsText?: string;
  badgeIcon?: string;
  badgeCoverImg?: string;
  /** Thai ("31 ธ.ค. 2026") or ISO ("2026-12-31") date */
  startDate?: string;
  endDate?: string;
  /** Computed by the server from endDate on every read; stored values are ignored */
  daysRemaining?: number;
  /** Whole days until startDate while the challenge has not started (derived, never stored); absent once it runs */
  startsInDays?: number;
  /** 'ended' is also derived by the server once endDate has passed */
  status?: 'draft' | 'active' | 'ended';
  image?: string;
  brandReward?: QuestReward;
  /** When set, the server counts the member's visits toward this challenge */
  rule?: QuestRule;
  /** Set by the server when a member proposed this challenge (it starts as a draft for staff to review) */
  createdByMemberId?: string;
  /** Set when a member's proposal was rejected in the review queue (it stays a hidden draft) */
  reviewRejectedAt?: string;
  rejectionReason?: string;
}

export interface PostComment {
  id: string;
  userName: string;
  userAvatar: string;
  text: string;
  content?: string;
  timeAgo: string;
}

export interface CommunityPost {
  id: string;
  userName: string;
  userAvatar: string;
  userBadge: string;
  eventId?: string;
  eventTitle?: string;
  category?: 'heal' | 'move' | 'chill' | 'learn';
  images: string[];
  caption: string;
  location: string;
  likesCount: number;
  commentsCount: number;
  sharesCount?: number;
  timeAgo: string;
  isLiked?: boolean;
  comments: PostComment[];
  targetType?: 'spot' | 'community' | 'fair' | 'challenge' | 'general';
  targetId?: string;
  targetTitle?: string;
}

